def max_sub_array_sum_repeated(arr, n, k):
    def kadane(a):
        max_so_far = curr = a[0]
        for x in a[1:]:
            curr = max(x, curr + x)
            max_so_far = max(max_so_far, curr)
        return max_so_far

    if n == 0:
        return 0
    if k == 1:
        return kadane(arr)
    if n == 1:
        return max(arr) * k if max(arr) > 0 else max(arr)

    total = sum(arr)
    if total > 0:
        return kadane(arr * 2) + total * (k - 2)
    else:
        return kadane(arr * min(k, 2))


